ERLAUBT = {"name", "klasse"}

def sortiert(spalte):
    if spalte not in ERLAUBT:
        raise ValueError("ungültige Spalte")
    sql = ("SELECT name FROM schueler "
           f"ORDER BY {spalte}")
    return con.execute(sql).fetchall()

def finde(id_text):
    sid = int(id_text)  # ValueError bei "x"
    if sid <= 0:
        raise ValueError("id muss > 0 sein")
    return con.execute(
        "SELECT name FROM schueler "
        "WHERE id = ?", (sid,)).fetchone()

print(finde("2"))     # ('Tim',)
print(sortiert("name; DROP TABLE x"))
